/* v12.1: Arabic / Russian native language (shared Englishia setting). Hebrew originals stay in _he. */
if (typeof window !== "undefined" && window.EnglishiaLang) window.EnglishiaLang.swapData(AGE_BANKS);

/* Mila Quest v10.2 — age-scaled question banks and helpers.
   Difficulty (speed / score) stays separate; age only changes the content. */

const esc = (s) => String(s == null ? "" : s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

export function wordsForAge(age, baseWords) {
  const key = age === "vz" || age === "ht" || age === "y12" ? age : "de";
  if (key === "de") return baseWords || [];
  return AGE_BANKS[key] || [];
}

export function speakText(item) {
  if (!item) return "";
  return item.speak || item.sentence || item.en || "";
}

export function spellTarget(item) {
  if (!item) return "";
  const s = item.spell || item.en || "";
  return /^[A-Za-z]{3,14}$/.test(s) ? s : "";
}

function uniqWrong(ans, list) {
  const out = [];
  const used = new Set([String(ans)]);
  for (const x of list || []) {
    const s = String(x == null ? "" : x);
    if (!s || used.has(s)) continue;
    used.add(s);
    out.push(s);
  }
  return out;
}

/** Build a special (sentence / gap / reading) prompt. Returns null for plain vocab (use the default word UI). */
export function questionOverride(mode, w) {
  if (!w || !w.kind || w.kind === "vocab") return null;

  if (w.kind === "gap" || w.kind === "grammar") {
    const filled = w.sentence || String(w.gap || "").replace(/_{2,}/g, w.gapAns);
    const wrongGap = uniqWrong(w.gapAns, w.gapOpts);
    if (mode === "let") {
      return { sub: "השלימו את החסר במשפט", q: `<span class="en gap-en">${esc(w.gap)}</span>${w.he ? `<div class="riddle">${esc(w.he)}</div>` : ""}`, answer: w.gapAns, wrong: wrongGap, extraT: 0.9, speak: w.speak || filled };
    }
    if (mode === "en2he") {
      return { sub: "מה פירוש המשפט בעברית?", q: `<span class="en">${esc(filled)}</span>`, answer: w.he, wrong: null, extraT: 0.8, speak: filled };
    }
    if (mode === "tr") {
      return { sub: "איך אומרים באנגלית? רצו אל השער", q: esc(w.he), answer: filled, wrong: null, extraT: 0.8, speak: filled };
    }
    if (mode === "picw" && w.pic) {
      return { sub: "מה בתמונה? רצו אל המשפט באנגלית", q: `<span class="pic-big">${w.pic}</span>`, answer: filled, wrong: null, extraT: 0.6, speak: filled };
    }
    if (mode === "rev") {
      return { sub: "🎧 הקשיבו למשפט באנגלית – מה הפירוש בעברית?", listen: true, answer: w.he, wrong: null, extraT: 1.1, speak: w.speak || filled };
    }
    if (mode === "hear") {
      return { sub: "🎧 הקשיבו – איזה משפט באנגלית שמעתם?", listen: true, answer: filled, wrong: null, extraT: 1.1, speak: w.speak || filled };
    }
    return null;
  }

  if (w.kind === "sentence") {
    const sent = w.sentence || w.en;
    if (mode === "en2he") {
      return { sub: "מה פירוש המשפט בעברית?", q: `<span class="en">${esc(sent)}</span>`, answer: w.he, wrong: null, extraT: 0.8, speak: sent };
    }
    if (mode === "tr") {
      return { sub: "איך אומרים באנגלית? רצו אל השער", q: esc(w.he), answer: sent, wrong: null, extraT: 0.8, speak: sent };
    }
    if (mode === "picw" && w.pic) {
      return { sub: "מה בתמונה? רצו אל המשפט באנגלית", q: `<span class="pic-big">${w.pic}</span>`, answer: sent, wrong: null, extraT: 0.6, speak: sent };
    }
    if (mode === "rev") {
      return { sub: "🎧 הקשיבו למשפט באנגלית – מה הפירוש בעברית?", listen: true, answer: w.he, wrong: null, extraT: 1.1, speak: w.speak || sent };
    }
    if (mode === "hear") {
      return { sub: "🎧 הקשיבו – איזה משפט באנגלית שמעתם?", listen: true, answer: sent, wrong: null, extraT: 1.1, speak: w.speak || sent };
    }
    return null; // let / build fall back to letters when the item is spellable
  }

  if (w.kind === "reading") {
    if (mode === "rev") {
      return { sub: w.questionHe || "🎧 הקשיבו וסמנו את הפירוש הנכון", q: w.questionHe ? `<div class="riddle">${esc(w.questionHe)}</div>` : "", listen: true, answer: w.ansHe, wrong: uniqWrong(w.ansHe, w.wrongHe), extraT: 1.5, speak: w.speak || w.passage };
    }
    if (mode === "hear") {
      return { sub: w.question || "🎧 הקשיבו וסמנו את התשובה הנכונה", q: w.question ? `<div class="riddle en">${esc(w.question)}</div>` : "", listen: true, answer: w.ans, wrong: uniqWrong(w.ans, w.wrong), extraT: 1.5, speak: w.speak || w.passage };
    }
    if (mode === "en2he") {
      return { sub: w.questionHe || "קראו את הקטע וענו", q: `<div class="passage en">${esc(w.passage)}</div><div class="riddle">${esc(w.questionHe || w.question)}</div>`, answer: w.ansHe, wrong: uniqWrong(w.ansHe, w.wrongHe), extraT: 1.7, speak: w.passage };
    }
    if (mode === "tr" || mode === "let" || mode === "picw") {
      return { sub: w.question || "Read the text and answer", q: `<div class="passage en">${esc(w.passage)}</div><div class="riddle en">${esc(w.question)}</div>`, answer: w.ans, wrong: uniqWrong(w.ans, w.wrong), extraT: 1.7, speak: w.passage };
    }
    return null;
  }
  return null;
}

/** Static check used by tests: every bank item has a correct key and no duplicate options. */
export function validateAgeBanks(baseWords) {
  const errs = [];
  const banks = { de: baseWords || [], vz: AGE_BANKS.vz, ht: AGE_BANKS.ht, y12: AGE_BANKS.y12 };
  for (const [age, bank] of Object.entries(banks)) {
    const ens = new Set();
    for (const it of bank) {
      if (!it || !it.en || !it.he || !it.w) errs.push(age + ": incomplete " + (it && it.en));
      if (ens.has(it.en)) errs.push(age + ": duplicate en " + it.en);
      ens.add(it.en);
      const ovModes = ["en2he","tr","let","picw","rev","hear"];
      for (const m of ovModes) {
        const q = questionOverride(m, it);
        if (!q) continue;
        const ans = q.answer;
        if (ans == null || ans === "") errs.push(age + " " + m + ": empty answer for " + it.en);
        if (q.wrong) {
          const opts = [ans, ...q.wrong];
          if (new Set(opts.map(String)).size !== opts.length) errs.push(age + " " + m + ": duplicate options for " + it.en);
          if (q.wrong.map(String).includes(String(ans))) errs.push(age + " " + m + ": answer in wrongs for " + it.en);
        }
      }
      if (it.kind === "gap") {
        const filled = (it.gap || "").replace(/_{2,}/g, it.gapAns);
        if (!it.gapAns || (it.gapOpts || []).includes(it.gapAns)) errs.push(age + ": bad gap " + it.en);
        if (it.gap && it.gap.includes("____") === false && !/_{2,}/.test(it.gap)) errs.push(age + ": gap blank " + it.en);
        if (it.sentence && it.gapAns && !String(it.sentence).includes(it.gapAns)) errs.push(age + ": gapAns mismatch " + it.en);
      }
    }
  }
  return { ok: errs.length === 0, errors: errs };
}

